    /// * `uow` - Active unit of work to execute the write within.
    /// * `record` - New global configuration values to persist.
    ///
    /// # Errors
    ///
    /// Returns `rusqlite::Error` if the update fails.
    pub fn update_global(
        uow: &UnitOfWork<'_>,
        record: &GlobalAgentConfigRow,
